<?php

/**
 * Generated by the Cybersalt Release Manager client kit.
 *
 * The "Link your account" panel. Included by AccountLinkHelper::panelHtml(),
 * which supplies $account, $canManage, $text, $notice and $noticeType. Change
 * the layout freely; the buttons only need their data-account-action attribute,
 * and the email box its name.
 *
 * @license     GNU General Public License version 2 or later
 */

defined('_JEXEC') or die;

use Joomla\CMS\HTML\HTMLHelper;
use Joomla\CMS\Language\Text;

$linked = $account['installation_id'] !== '' && $account['email_hash'] !== '';
$state  = $linked ? ($account['status'] ?: 'denied') : 'unlinked';

$badges = [
    'active'       => 'success',
    'lapsed'       => 'warning',
    'not_a_member' => 'info',
    'over_limit'   => 'warning',
    'blacklisted'  => 'danger',
    'denied'       => 'danger',
];

// The store's renewal or sign-up page, whichever applies to this answer.
$ctaUrl   = '';
$ctaLabel = '';

if ($state === 'lapsed' && $account['renewal_url'] !== '') {
    $ctaUrl   = $account['renewal_url'];
    $ctaLabel = $text('RENEW');
} elseif ($state === 'not_a_member' && ($account['signup_url'] ?: $account['renewal_url']) !== '') {
    $ctaUrl   = $account['signup_url'] ?: $account['renewal_url'];
    $ctaLabel = $text('BUY');
}

// Only http(s) links from the store are rendered as buttons.
if ($ctaUrl !== '' && !preg_match('#^https?://#i', $ctaUrl)) {
    $ctaUrl = '';
}

$emailBox = static function () use ($account, $text): string {
    $id = 'csrm-account-email-' . uniqid();

    return '<div class="row g-2 align-items-end mt-1">'
        . '<div class="col-sm-7 col-md-6">'
        . '<label class="form-label" for="' . $id . '">' . $text('EMAIL_LABEL') . '</label>'
        . '<input type="email" class="form-control" id="' . $id . '" name="account_email"'
        . ' value="' . htmlspecialchars($account['email'], ENT_QUOTES, 'UTF-8') . '" autocomplete="email">'
        . '</div>'
        . '<div class="col-auto">'
        . '<button type="button" class="btn btn-primary" data-account-action="link">' . $text('LINK_BUTTON') . '</button>'
        . '</div>'
        . '</div>';
};
?>
<div class="card mb-4 border-<?php echo $badges[$state] ?? 'primary'; ?>">
    <div class="card-header d-flex justify-content-between align-items-center">
        <h3 class="card-title mb-0"><?php echo $text('TITLE'); ?></h3>
        <?php if ($linked) : ?>
            <span class="badge bg-<?php echo $badges[$state] ?? 'secondary'; ?>">
                <?php echo $text('STATE_' . strtoupper($state)); ?>
            </span>
        <?php endif; ?>
    </div>
    <div class="card-body">
        <div class="alert alert-warning d-none" data-account-error role="alert"></div>

        <?php if ($notice !== '') : ?>
            <div class="alert alert-<?php echo htmlspecialchars($noticeType, ENT_QUOTES, 'UTF-8'); ?>" role="status"><?php echo htmlspecialchars($notice, ENT_QUOTES, 'UTF-8', false); ?></div>
        <?php endif; ?>

        <?php if (!$linked) : ?>
            <p class="mb-2"><?php echo $text('INTRO'); ?></p>
            <?php if ($canManage) : ?>
                <?php echo $emailBox(); ?>
            <?php else : ?>
                <p class="text-muted mb-0"><?php echo $text('ADMIN_ONLY'); ?></p>
            <?php endif; ?>
        <?php else : ?>
            <p class="mb-2">
                <?php echo Text::sprintf('COM_KITDEMO_ACCOUNT_LINKED_AS', htmlspecialchars($account['email'], ENT_QUOTES, 'UTF-8')); ?>
                <?php if ($account['last_verified'] > 0) : ?>
                    <span class="text-muted small">
                        &middot; <?php echo Text::sprintf('COM_KITDEMO_ACCOUNT_CHECKED', HTMLHelper::_('date', '@' . $account['last_verified'], Text::_('DATE_FORMAT_LC2'))); ?>
                    </span>
                <?php endif; ?>
            </p>

            <?php if ($state === 'active') : ?>
                <p class="mb-3"><?php echo $text('ACTIVE_TEXT'); ?></p>
            <?php elseif ($account['message'] !== '') : ?>
                <div class="alert alert-<?php echo $badges[$state] ?? 'secondary'; ?> mb-3"><?php echo htmlspecialchars($account['message'], ENT_QUOTES, 'UTF-8'); ?></div>
            <?php endif; ?>

            <?php if ($ctaUrl !== '') : ?>
                <p class="mb-3">
                    <a class="btn btn-success" href="<?php echo htmlspecialchars($ctaUrl, ENT_QUOTES, 'UTF-8'); ?>" target="_blank" rel="noopener noreferrer"><?php echo $ctaLabel; ?></a>
                </p>
            <?php endif; ?>

            <?php if ($canManage) : ?>
                <div class="d-flex flex-wrap gap-2">
                    <button type="button" class="btn btn-sm btn-outline-primary" data-account-action="refresh"><?php echo $text('REFRESH_BUTTON'); ?></button>
                    <button type="button" class="btn btn-sm btn-outline-danger" data-account-action="unlink"><?php echo $text('UNLINK_BUTTON'); ?></button>
                </div>

                <?php if ($state !== 'active' && $state !== 'blacklisted') : ?>
                    <hr>
                    <p class="mb-1 small text-muted"><?php echo $text('TRY_OTHER'); ?></p>
                    <?php echo $emailBox(); ?>
                <?php endif; ?>
            <?php endif; ?>
        <?php endif; ?>
    </div>
</div>
